          nakadaka: { en: "Nakadaka (Mid-High \u2461+)", ja: "\u4E2D\u9AD8\u578B", bn: "\u09A8\u09BE\u0995\u09BE\u09A6\u09BE\u0995\u09BE (\u09AE\u09BE\u099D\u0996\u09BE\u09A8\u09C7\u09B0 \u09AE\u09CB\u09B0\u09BE \u0989\u099A\u09CD\u099A \u2461+)" },
          odaka: { en: "Odaka (Tail-High N)", ja: "\u5C3E\u9AD8\u578B", bn: "\u0993\u09A6\u09BE\u0995\u09BE (\u09B6\u09C7\u09B7 \u09AE\u09CB\u09B0\u09BE \u0989\u099A\u09CD\u099A N)" }
