          trxId: finalTrxID,
          planId: planTier,
          planName: SUBSCRIPTION_TIERS[planTier].nameBn,
          amount,
          submittedAt: (/* @__PURE__ */ new Date()).toISOString(),
          status: "approved",
          approvedAt: (/* @__PURE__ */ new Date()).toISOString(),
