init_subscriptionService();
function requireSubscription(requiredTier = "n5_pro") {
  return async (req, res, next) => {
    try {
      const user = req.user;
      if (user?.role === "founder" || user?.role === "admin" || user?.email === "mdtanvirkabirbiplob@gmail.com") {
        return next();
      }
      const identifier = user?.id || user?.email || req.headers["x-user-id"] || req.query.userId;
      if (!identifier) {
        return res.status(401).json({
          success: false,
          paywall: true,
          error: "Authentication Required",
          message: "\u09AA\u09CD\u09B0\u09BF\u09AE\u09BF\u09AF\u09BC\u09BE\u09AE \u0995\u09A8\u099F\u09C7\u09A8\u09CD\u099F \u0985\u09CD\u09AF\u09BE\u0995\u09CD\u09B8\u09C7\u09B8 \u0995\u09B0\u09A4\u09C7 \u0985\u09A8\u09C1\u0997\u09CD\u09B0\u09B9 \u0995\u09B0\u09C7 \u09B2\u0997\u0987\u09A8 \u0995\u09B0\u09C1\u09A8\u0964",
          requiredTier
        });
      }
      const access = await subscriptionService.canAccess(identifier, requiredTier);
      if (!access.allowed) {
        return res.status(402).json({
          success: false,
          paywall: true,
          error: "Subscription Required",
          requiredTier,
          currentTier: access.currentTier,
          message: access.reason || "\u098F\u0987 \u09AB\u09BF\u099A\u09BE\u09B0\u099F\u09BF \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09A4\u09C7 N5 \u09AA\u09CD\u09B0\u09CB \u09B8\u09BE\u09AC\u09B8\u09CD\u0995\u09CD\u09B0\u09BF\u09AA\u09B6\u09A8 \u09AA\u09CD\u09B0\u09DF\u09CB\u099C\u09A8\u0964",
          plans: subscriptionService.getCatalog().filter((p) => p.id !== "free")
        });
      }
      next();
    } catch (err) {
      console.error("[SubscriptionGate] Error verifying subscription:", err);
      return res.status(500).json({
        success: false,
        error: "Subscription Verification Error",
        message: "\u09B8\u09BE\u09AC\u09B8\u09CD\u0995\u09CD\u09B0\u09BF\u09AA\u09B6\u09A8 \u09B8\u09CD\u099F\u09CD\u09AF\u09BE\u099F\u09BE\u09B8 \u09AF\u09BE\u099A\u09BE\u0987 \u0995\u09B0\u09A4\u09C7 \u09B8\u09AE\u09B8\u09CD\u09AF\u09BE \u09B9\u09DF\u09C7\u099B\u09C7\u0964"
      });
    }
  };
}

// server/services/mockExamPersistenceService.ts
init_prisma();
init_supabase();
init_db();
import crypto8 from "crypto";
var MockExamPersistenceService = class {
  static {
    this.tableInitialized = false;
  }
  /**
   * Generates a 32-character SHA256 cryptographic verification hash for an official exam certificate.
   */
  static generateVerificationHash(attempt) {
    const rawPayload = `${attempt.certificateId}:${attempt.userId}:${attempt.examCode}:${attempt.totalScaledScore}:${attempt.submittedAt}:nihomi_jlpt_n5_official_verify`;
    return crypto8.createHash("sha256").update(rawPayload).digest("hex").substring(0, 32);
  }
  /**
   * Ensures the PostgreSQL `mock_exam_results` table exists.
   */
  static async ensureTableExists() {
    if (this.tableInitialized || !isDatabaseConfigured()) return;
    try {
      await prisma.$executeRawUnsafe(`
        CREATE TABLE IF NOT EXISTS mock_exam_results (
          id VARCHAR(64) PRIMARY KEY,
          user_id VARCHAR(128) NOT NULL,
          mock_exam_id VARCHAR(64) NOT NULL,
          exam_code VARCHAR(64) NOT NULL,
          level VARCHAR(16) NOT NULL,
          started_at TIMESTAMPTZ NOT NULL,
          submitted_at TIMESTAMPTZ NOT NULL,
          time_spent_seconds INT NOT NULL,
          section_scores JSONB NOT NULL,
          total_scaled_score INT NOT NULL,
          overall_passing_score INT NOT NULL,
          is_passed BOOLEAN NOT NULL,
          fail_reason TEXT,
          letter_grade VARCHAR(8),
          percentile_rank INT,
          certificate_id VARCHAR(64),
          verification_hash VARCHAR(64),
          user_answers JSONB,
          strength_summary_bn TEXT,
          weakness_summary_bn TEXT,
          actionable_study_plan_bn JSONB,
          created_at TIMESTAMPTZ DEFAULT NOW()
        );
      `);
      this.tableInitialized = true;
    } catch (err) {
      console.warn("[MockExamPersistence] Prisma executeRaw table init notice:", err?.message || err);
    }
  }
  /**
   * Persists an official mock exam attempt to PostgreSQL / Supabase storage.
   */
  static async persistAttempt(attempt) {
    const verificationHash = attempt.verificationHash || this.generateVerificationHash(attempt);
    attempt.verificationHash = verificationHash;
    if (isDatabaseConfigured()) {
      try {
        await this.ensureTableExists();
        await prisma.$executeRawUnsafe(
          `
          INSERT INTO mock_exam_results (
            id, user_id, mock_exam_id, exam_code, level, started_at, submitted_at,
            time_spent_seconds, section_scores, total_scaled_score, overall_passing_score,
            is_passed, fail_reason, letter_grade, percentile_rank, certificate_id,
            verification_hash, user_answers, strength_summary_bn, weakness_summary_bn,
            actionable_study_plan_bn, created_at
          ) VALUES (
            $1, $2, $3, $4, $5, $6::timestamptz, $7::timestamptz,
            $8, $9::jsonb, $10, $11,
            $12, $13, $14, $15, $16,
            $17, $18::jsonb, $19, $20,
            $21::jsonb, NOW()
          )
          ON CONFLICT (id) DO UPDATE SET
            section_scores = EXCLUDED.section_scores,
            total_scaled_score = EXCLUDED.total_scaled_score,
            is_passed = EXCLUDED.is_passed,
            letter_grade = EXCLUDED.letter_grade,
            verification_hash = EXCLUDED.verification_hash;
          `,
          attempt.id,
          attempt.userId,
          attempt.mockExamId,
          attempt.examCode,
          attempt.level,
          attempt.startedAt,
          attempt.submittedAt,
          attempt.timeSpentSeconds,
          JSON.stringify(attempt.sectionScores),
          attempt.totalScaledScore,
          attempt.overallPassingScore,
          attempt.isPassed,
          attempt.failReason || null,
          attempt.letterGrade,
          attempt.percentileRank || 0,
          attempt.certificateId,
          verificationHash,
          JSON.stringify(attempt.userAnswers || []),
          attempt.strengthSummaryBn || "",
          attempt.weaknessSummaryBn || "",
          JSON.stringify(attempt.actionableStudyPlanBn || [])
        );
        console.log(`[MockExamPersistence] Attempt ${attempt.id} saved to PostgreSQL successfully.`);
        return { success: true, hash: verificationHash };
      } catch (prismaErr) {
        console.warn("[MockExamPersistence] Prisma attempt save error, trying Supabase fallback:", prismaErr?.message || prismaErr);
      }
    }
    try {
      const { error: sbError } = await supabase.from("mock_exam_results").upsert({
        id: attempt.id,
        user_id: attempt.userId,
        mock_exam_id: attempt.mockExamId,
        exam_code: attempt.examCode,
        level: attempt.level,
        started_at: attempt.startedAt,
        submitted_at: attempt.submittedAt,
        time_spent_seconds: attempt.timeSpentSeconds,
        section_scores: attempt.sectionScores,
        total_scaled_score: attempt.totalScaledScore,
        overall_passing_score: attempt.overallPassingScore,
        is_passed: attempt.isPassed,
        fail_reason: attempt.failReason || null,
        letter_grade: attempt.letterGrade,
        percentile_rank: attempt.percentileRank || 0,
        certificate_id: attempt.certificateId,
        verification_hash: verificationHash,
        user_answers: attempt.userAnswers || [],
        strength_summary_bn: attempt.strengthSummaryBn || "",
        weakness_summary_bn: attempt.weaknessSummaryBn || "",
        actionable_study_plan_bn: attempt.actionableStudyPlanBn || []
      });
      if (sbError) {
        console.warn("[MockExamPersistence] Supabase write error:", sbError.message);
      } else {
        console.log(`[MockExamPersistence] Attempt ${attempt.id} saved to Supabase successfully.`);
        return { success: true, hash: verificationHash };
      }
    } catch (sbErr) {
      console.warn("[MockExamPersistence] Supabase exception:", sbErr?.message || sbErr);
    }
    return { success: false, hash: verificationHash };
  }
  /**
   * Public verification helper for certificate QR / URL checks
   */
  static async verifyCertificate(certificateId) {
    const allAttempts = db.data.mockExamAttempts;
    const localAttempt = allAttempts?.find((a) => a.certificateId === certificateId);
    if (localAttempt) {
      const user = db.findUserById(localAttempt.userId);
      const profile = db.getProfileByUserId(localAttempt.userId);
      const studentName = profile?.displayName || user?.email?.split("@")[0] || "Nihomi Student";
      return {
        found: true,
        isPassed: localAttempt.isPassed,
        studentName,
        examCode: localAttempt.examCode,
        level: localAttempt.level,
        totalScaledScore: localAttempt.totalScaledScore,
        letterGrade: localAttempt.letterGrade,
        submittedAt: localAttempt.submittedAt,
        verificationHash: localAttempt.verificationHash || this.generateVerificationHash(localAttempt)
      };
    }
    if (isDatabaseConfigured()) {
      try {
        const rows = await prisma.$queryRawUnsafe(
          "SELECT * FROM mock_exam_results WHERE certificate_id = $1 LIMIT 1",
          certificateId
        );
        if (rows && rows.length > 0) {
          const row = rows[0];
          const user = db.findUserById(row.user_id);
          const profile = db.getProfileByUserId(row.user_id);
          const studentName = profile?.displayName || user?.email?.split("@")[0] || "Nihomi Student";
          return {
            found: true,
            isPassed: row.is_passed,
            studentName,
            examCode: row.exam_code,
            level: row.level,
            totalScaledScore: row.total_scaled_score,
            letterGrade: row.letter_grade,
            submittedAt: row.submitted_at,
            verificationHash: row.verification_hash
          };
        }
      } catch {
      }
    }
    return { found: false };
  }
};

// server/routes/mockExams.ts
init_subscriptionService();
var mockExamsRouter = Router12();
mockExamsRouter.get("/verify-certificate/:certificateId", async (req, res) => {
  try {
    const cert = await MockExamPersistenceService.verifyCertificate(req.params.certificateId);
    if (!cert.found) {
      return res.status(404).json({ success: false, error: "Certificate not found or invalid" });
    }
    return res.json({ success: true, certificate: cert });
  } catch (err) {
    return res.status(500).json({ success: false, error: err.message });
  }
});
mockExamsRouter.get("/", optionalAuth2, (req, res) => {
  try {
    const level = req.query.level;
    const exams = db.getMockExams(level);
    let userAttempts = [];
    if (req.user) {
      userAttempts = db.getUserMockExamAttempts(req.user.id);
    }
    const summary = exams.map((exam) => {
      const pastForThis = userAttempts.filter((a) => a.mockExamId === exam.id || a.examCode === exam.examCode);
      const bestAttempt = pastForThis.sort((a, b) => b.totalScaledScore - a.totalScaledScore)[0];
      return {
        id: exam.id,
        examCode: exam.examCode,
        title: exam.title,
        titleJa: exam.titleJa,
        level: exam.level,
        description: exam.description,
        descriptionBn: exam.descriptionBn,
        totalTimeMinutes: exam.totalTimeMinutes,
        totalPossibleScore: exam.totalPossibleScore,
        overallPassingScore: exam.overallPassingScore,
        sectionCount: exam.sections.length,
        totalQuestions: exam.sections.reduce((acc, s) => acc + s.questions.length, 0),
        sectionBreakdown: exam.sections.map((s) => ({
          sectionType: s.sectionType,
          title: s.title,
          timeLimitMinutes: s.timeLimitMinutes,
          questionCount: s.questions.length,
          maxScaledScore: s.maxScaledScore,
          passingThreshold: s.passingThreshold
        })),
        userBestAttempt: bestAttempt ? {
          attemptId: bestAttempt.id,
          totalScaledScore: bestAttempt.totalScaledScore,
          isPassed: bestAttempt.isPassed,
          letterGrade: bestAttempt.letterGrade,
          submittedAt: bestAttempt.submittedAt
        } : null,
        attemptCount: pastForThis.length
      };
    });
    return res.json({ success: true, mockExams: summary });
  } catch (error) {
    console.error("Error fetching mock exams:", error);
    return res.status(500).json({ success: false, error: error.message || "Failed to fetch mock exams" });
  }
});
mockExamsRouter.get("/:id", optionalAuth2, requireSubscription("n5_pro"), (req, res) => {
  try {
    const exam = db.getMockExamById(req.params.id);
    if (!exam) {
      return res.status(404).json({ success: false, error: "Mock Exam not found" });
    }
    const sanitizedSections = exam.sections.map((sec) => ({
      id: sec.id,
      sectionType: sec.sectionType,
      title: sec.title,
      titleJa: sec.titleJa,
      timeLimitMinutes: sec.timeLimitMinutes,
      maxScaledScore: sec.maxScaledScore,
      passingThreshold: sec.passingThreshold,
      questions: sec.questions.map((q) => ({
        id: q.id,
        sectionType: q.sectionType,
        questionNumber: q.questionNumber,
        type: q.type,
        questionText: q.questionText,
        questionTextJa: q.questionTextJa,
        furigana: q.furigana,
        readingPassage: q.readingPassage,
        audioScript: q.audioScript,
        scrambledParts: q.scrambledParts,
        starPositionIndex: q.starPositionIndex,
        options: q.options,
        pointValue: q.pointValue,
        conceptCode: q.conceptCode
      }))
    }));
    let userPastAttempts = [];
    if (req.user) {
      userPastAttempts = db.getUserMockExamAttempts(req.user.id).filter(
        (a) => a.mockExamId === exam.id || a.examCode === exam.examCode
      );
    }
    return res.json({
      success: true,
      mockExam: {
        id: exam.id,
        examCode: exam.examCode,
        title: exam.title,
        titleJa: exam.titleJa,
        level: exam.level,
        description: exam.description,
        descriptionBn: exam.descriptionBn,
        totalTimeMinutes: exam.totalTimeMinutes,
        totalPossibleScore: exam.totalPossibleScore,
        overallPassingScore: exam.overallPassingScore,
        sections: sanitizedSections
      },
      userPastAttempts
    });
  } catch (error) {
    console.error("Error fetching mock exam detail:", error);
    return res.status(500).json({ success: false, error: error.message || "Failed to fetch mock exam detail" });
  }
});
mockExamsRouter.post("/:id/submit", requireAuth2, requireSubscription("n5_pro"), async (req, res) => {
  try {
    const { answers, sectionTimesSpentSeconds, totalTimeSpentSeconds } = req.body;
    if (!answers || !Array.isArray(answers)) {
      return res.status(400).json({ success: false, error: "answers array is required" });
    }
    const result = db.recordMockExamAttempt({
      userId: req.user.id,
      mockExamId: req.params.id,
      answers,
      sectionTimesSpentSeconds: sectionTimesSpentSeconds || {
        vocabulary: 0,
        grammar_reading: 0,
        listening: 0
      },
      totalTimeSpentSeconds: totalTimeSpentSeconds || 60
    });
    const userSub = await subscriptionService.getUserSubscription(req.user.id);
    const isPro = userSub.tier === "n5_pro" || userSub.tier === "n5_lifetime" || req.user.role === "admin" || req.user.role === "founder";
    result.attempt.isPro = isPro;
    await MockExamPersistenceService.persistAttempt(result.attempt);
    const exam = db.getMockExamById(req.params.id);
    const detailedReviewSections = exam?.sections.map((sec) => ({
      id: sec.id,
      sectionType: sec.sectionType,
      title: sec.title,
      questions: sec.questions.map((q) => {
        const userAns = result.attempt.userAnswers.find((a) => a.questionId === q.id);
        return {
          id: q.id,
          questionNumber: q.questionNumber,
          type: q.type,
          questionText: q.questionText,
          questionTextJa: q.questionTextJa,
          furigana: q.furigana,
          readingPassage: q.readingPassage,
          audioScript: q.audioScript,
          scrambledParts: q.scrambledParts,
          starPositionIndex: q.starPositionIndex,
          options: q.options,
          correctOptionIndex: q.correctOptionIndex,
          selectedOptionIndex: userAns ? userAns.selectedOptionIndex : -1,
          isCorrect: userAns ? userAns.isCorrect : false,
          explanationJa: q.explanationJa,
          explanationBn: q.explanationBn,
          explanationEn: q.explanationEn,
          conceptCode: q.conceptCode
        };
      })
    }));
    return res.json({
      success: true,
      attempt: result.attempt,
      reviewSections: detailedReviewSections,
      message: result.message
    });
  } catch (error) {
    console.error("Error recording mock exam attempt:", error);
    return res.status(500).json({ success: false, error: error.message || "Failed to submit mock exam" });
  }
});
