init_db();
import fs4 from "fs";
import path4 from "path";
import crypto9 from "crypto";
var CloudStorageService = class {
  constructor() {
    this.sourcesDir = path4.join(process.cwd(), "server", "data", "content_sources");
    this.mediaDir = path4.join(process.cwd(), "server", "data", "media");
    this.ensureDirs();
  }
  ensureDirs() {
    if (!fs4.existsSync(this.sourcesDir)) {
      fs4.mkdirSync(this.sourcesDir, { recursive: true });
    }
    if (!fs4.existsSync(this.mediaDir)) {
      fs4.mkdirSync(this.mediaDir, { recursive: true });
    }
  }
  get sourcesBucket() {
    return process.env.SUPABASE_STORAGE_BUCKET_SOURCES || "nihomi-content-sources";
  }
  get mediaBucket() {
    return process.env.SUPABASE_STORAGE_BUCKET_MEDIA || "nihomi-curriculum-media";
  }
  /**
   * Uploads a file buffer to Cloud Media Storage (Supabase Storage) with automatic local disk caching.
   */
  async uploadFile(params) {
    this.ensureDirs();
    const bucket = params.bucketName || (params.mimeType.startsWith("image/") || params.mimeType.startsWith("audio/") ? this.mediaBucket : this.sourcesBucket);
    const sanitizedFilename = params.filename.replace(/[^a-zA-Z0-9._-]/g, "_");
    const folderPrefix = params.folder ? `${params.folder.replace(/^\/+|\/+$/g, "")}/` : "";
    const storageKey = `${folderPrefix}${crypto9.randomUUID()}_${sanitizedFilename}`;
    const targetDir = bucket === this.mediaBucket ? this.mediaDir : this.sourcesDir;
    const localFilePath = path4.join(targetDir, storageKey.replace(/\//g, "_"));
    await fs4.promises.writeFile(localFilePath, params.buffer);
    let isCloudSynced = false;
    let storageUrl = `/api/content/media/${encodeURIComponent(storageKey)}`;
    const supabase3 = db.getSupabaseClient();
    if (supabase3) {
      try {
        const { data, error } = await supabase3.storage.from(bucket).upload(storageKey, params.buffer, {
          contentType: params.mimeType,
          upsert: true,
          cacheControl: "3600"
        });
        if (!error && data) {
          isCloudSynced = true;
          if (params.isPublic !== false) {
            const { data: publicData } = supabase3.storage.from(bucket).getPublicUrl(storageKey);
            if (publicData?.publicUrl) {
              storageUrl = publicData.publicUrl;
            }
          }
        } else if (error) {
          console.warn(`[CloudStorage] Supabase bucket upload notice (${bucket}/${storageKey}):`, error.message);
        }
      } catch (err) {
        console.warn(`[CloudStorage] Cloud upload warning for ${storageKey}:`, err?.message || err);
      }
    }
    return {
      success: true,
      storageKey,
      storagePath: localFilePath,
      storageUrl,
      bucketName: bucket,
      fileSize: params.buffer.length,
      mimeType: params.mimeType,
      isCloudSynced
    };
  }
  /**
   * Retrieves a file buffer either from local disk cache or directly from Supabase Storage.
   */
  async getFileBuffer(storageKey, bucketName, localFallbackPath) {
    if (localFallbackPath && fs4.existsSync(localFallbackPath)) {
      return await fs4.promises.readFile(localFallbackPath);
    }
    const bucket = bucketName || this.sourcesBucket;
    const targetDir = bucket === this.mediaBucket ? this.mediaDir : this.sourcesDir;
    const localFilePath = path4.join(targetDir, storageKey.replace(/\//g, "_"));
    if (fs4.existsSync(localFilePath)) {
      return await fs4.promises.readFile(localFilePath);
    }
    const supabase3 = db.getSupabaseClient();
    if (supabase3) {
      try {
        const { data, error } = await supabase3.storage.from(bucket).download(storageKey);
        if (!error && data) {
          const arrayBuffer = await data.arrayBuffer();
          const buffer = Buffer.from(arrayBuffer);
          await fs4.promises.writeFile(localFilePath, buffer).catch(() => {
          });
          return buffer;
        }
      } catch (err) {
        console.warn(`[CloudStorage] Could not fetch remote file ${storageKey} from bucket ${bucket}:`, err);
      }
    }
    return null;
  }
  /**
   * Generates a signed access URL for private files.
   */
  async getSignedUrl(storageKey, bucketName, expiresInSeconds = 3600) {
    const bucket = bucketName || this.sourcesBucket;
    const supabase3 = db.getSupabaseClient();
    if (supabase3) {
      try {
        const { data, error } = await supabase3.storage.from(bucket).createSignedUrl(storageKey, expiresInSeconds);
        if (!error && data?.signedUrl) {
          return data.signedUrl;
        }
      } catch (err) {
        console.warn(`[CloudStorage] Signed URL generation error for ${storageKey}:`, err);
      }
    }
    return `/api/content/media/${encodeURIComponent(storageKey)}`;
  }
  /**
   * Deletes a file from both Cloud Storage and local cache.
   */
  async deleteFile(storageKey, bucketName, localPath) {
    let deleted = false;
    if (localPath && fs4.existsSync(localPath)) {
      try {
        await fs4.promises.unlink(localPath);
        deleted = true;
      } catch {
      }
    }
    const bucket = bucketName || this.sourcesBucket;
    const targetDir = bucket === this.mediaBucket ? this.mediaDir : this.sourcesDir;
    const localFilePath = path4.join(targetDir, storageKey.replace(/\//g, "_"));
    if (fs4.existsSync(localFilePath)) {
      try {
        await fs4.promises.unlink(localFilePath);
        deleted = true;
      } catch {
      }
    }
    const supabase3 = db.getSupabaseClient();
    if (supabase3) {
      try {
        await supabase3.storage.from(bucket).remove([storageKey]);
        deleted = true;
      } catch {
      }
    }
    return deleted;
  }
};
