    modelAnswerJa: "\u3059\u307F\u307E\u305B\u3093\u3001\u30AB\u30E1\u30E9\u3046\u308A\u3070\u306F \u3069\u3053\u3067\u3059\u304B\u3002\uFF12\u304B\u3044\u3067\u3059\u3002\u3053\u306E \u30AB\u30E1\u30E9\u306F \u3044\u304F\u3089\u3067\u3059\u304B\u3002\u3055\u3093\u307E\u3093\u3048\u3093\u3067\u3059\u3002\u3058\u3083\u3001\u3053\u308C\u3092 \u304F\u3060\u3055\u3044\u3002",
    modelAnswerBn: "\u09AE\u09BE\u09AB \u0995\u09B0\u09AC\u09C7\u09A8, \u0995\u09CD\u09AF\u09BE\u09AE\u09C7\u09B0\u09BE \u0995\u09BE\u0989\u09A8\u09CD\u099F\u09BE\u09B0 \u0995\u09CB\u09A5\u09BE\u09AF\u09BC? \u09E8 \u09A4\u09B2\u09BE\u09AF\u09BC\u0964 \u098F\u0987 \u0995\u09CD\u09AF\u09BE\u09AE\u09C7\u09B0\u09BE\u099F\u09BF\u09B0 \u09A6\u09BE\u09AE \u0995\u09A4? \u09E9\u09E6,\u09E6\u09E6\u09E6 \u0987\u09AF\u09BC\u09C7\u09A8\u0964 \u09A4\u09BE\u09B9\u09B2\u09C7 \u0986\u09AE\u09BE\u0995\u09C7 \u098F\u099F\u09BF \u09A6\u09BF\u09A8\u0964"
