        options: ["\u09B0\u09AC\u09BF\u09AC\u09BE\u09B0 \u0993 \u09B8\u09CB\u09AE\u09AC\u09BE\u09B0", "\u09B6\u09C1\u0995\u09CD\u09B0\u09AC\u09BE\u09B0 \u0993 \u09B6\u09A8\u09BF\u09AC\u09BE\u09B0", "\u09B6\u09A8\u09BF\u09AC\u09BE\u09B0 \u0993 \u09B0\u09AC\u09BF\u09AC\u09BE\u09B0", "\u09B6\u09C1\u09A7\u09C1 \u09B0\u09AC\u09BF\u09AC\u09BE\u09B0"],
