    promptBn: "\u0986\u09AA\u09A8\u09BF \u0995\u09AC\u09C7 \u099C\u09BE\u09AA\u09BE\u09A8\u09C7 \u09AF\u09BE\u09AC\u09C7\u09A8 \u09AC\u09BE \u0997\u09BF\u09AF\u09BC\u09C7\u099B\u09BF\u09B2\u09C7\u09A8, \u0995\u09C0\u09B8\u09C7 \u0995\u09B0\u09C7 \u09AF\u09BE\u09AC\u09C7\u09A8 \u098F\u09AC\u0982 \u0995\u09BE\u09B0 \u09B8\u09BE\u09A5\u09C7 \u09AF\u09BE\u09AC\u09C7\u09A8\u2014\u09A4\u09BE \u09EA \u09AC\u09BE\u0995\u09CD\u09AF\u09C7 \u099C\u09BE\u09AA\u09BE\u09A8\u09BF\u09A4\u09C7 \u09B2\u09BF\u0996\u09C1\u09A8\u0964",
