    {
      id: "gram-7-2",
      pattern: "Person \u306B \u3042\u3052\u307E\u3059 / \u3082\u3089\u3044\u307E\u3059 & \u3082\u3046\u301C\u307E\u3057\u305F (\u0986\u09A6\u09BE\u09A8-\u09AA\u09CD\u09B0\u09A6\u09BE\u09A8 \u0993 \u09B8\u09AE\u09CD\u09AA\u09A8\u09CD\u09A8\u09A4\u09BE)",
      structureFormula: "[Person] + \u306B + [Object] + \u3092 + \u3042\u3052\u307E\u3059 / \u3082\u3089\u3044\u307E\u3059",
      meaningEn: "Give to / Receive from / Already did",
      meaningBn: "\u0995\u09BE\u0989\u0995\u09C7 \u0995\u09BF\u099B\u09C1 \u09A6\u09C7\u0993\u09DF\u09BE (\u306B \u3042\u3052\u307E\u3059), \u0995\u09BE\u09B0\u09CB \u0995\u09BE\u099B \u09A5\u09C7\u0995\u09C7 \u09A8\u09C7\u0993\u09DF\u09BE (\u306B \u3082\u3089\u3044\u307E\u3059) \u098F\u09AC\u0982 \u0987\u09A4\u09BF\u09AE\u09A7\u09CD\u09AF\u09C7 \u0995\u09BE\u099C \u09B8\u09AE\u09CD\u09AA\u09A8\u09CD\u09A8 \u09B9\u0993\u09DF\u09BE (\u3082\u3046\u301C\u307E\u3057\u305F)",
      detailedExplanationBn: "\u09AF\u09BE\u0995\u09C7 \u0995\u09BF\u099B\u09C1 \u09A6\u09C7\u0993\u09DF\u09BE \u09B9\u09DF, \u09A4\u09BE\u09B0 \u09A8\u09BE\u09AE\u09C7\u09B0 \u09AA\u09B0\u09C7 \u306B \u09AC\u09B8\u09C7 (\u09AF\u09C7\u09AE\u09A8: \u09AA\u09BF\u09A4\u09BE\u0995\u09C7 \u0989\u09AA\u09B9\u09BE\u09B0 \u09A6\u09BF\u0987 - \u3061\u3061\u306B \u3042\u3052\u307E\u3059)\u0964 \u0986\u09AC\u09BE\u09B0 \u09AF\u09BE\u09B0 \u0995\u09BE\u099B \u09A5\u09C7\u0995\u09C7 \u0995\u09BF\u099B\u09C1 \u09AA\u09BE\u0993\u09DF\u09BE \u09AF\u09BE\u09DF, \u09A4\u09BE\u09B0 \u09AA\u09B0\u09C7\u0993 \u306B (\u09AC\u09BE \u304B\u3089) \u09AC\u09B8\u09C7\u0964 \u0986\u09B0 \u0995\u09BE\u099C \u0987\u09A4\u09BF\u09AE\u09A7\u09CD\u09AF\u09C7 \u09B9\u09DF\u09C7 \u0997\u09C7\u09B2\u09C7 \u3082\u3046 \u301C\u307E\u3057\u305F \u09AC\u09B2\u09BE \u09B9\u09DF\u0964 \u098F\u0996\u09A8\u0993 \u09A8\u09BE \u09B9\u09B2\u09C7 \u307E\u3060\u3067\u3059 (\u09AE\u09BE\u09A6\u09BE \u09A6\u09C7\u09B8\u09C1) \u09AC\u09B2\u09A4\u09C7 \u09B9\u09DF\u0964",
      formationRules: [
        "\u0997\u09CD\u09B0\u09B9\u09C0\u09A4\u09BE + \u306B + \u09AC\u09B8\u09CD\u09A4\u09C1 + \u3092 + \u3042\u3052\u307E\u3059",
        "\u09A6\u09BE\u09A4\u09BE + \u306B/\u304B\u3089 + \u09AC\u09B8\u09CD\u09A4\u09C1 + \u3092 + \u3082\u3089\u3044\u307E\u3057\u305F",
        "\u3082\u3046 + Verb-\u307E\u3057\u305F (\u0987\u09A4\u09CB\u09AE\u09A7\u09CD\u09AF\u09C7 \u0995\u09B0\u09C7\u099B\u09BF)"
      ],
      commonMistakesBn: [
        '\u3082\u3046 \u098F\u09B0 \u09A8\u09BE-\u09AC\u09CB\u09A7\u0995\u09C7 "\u301C\u307E\u305B\u3093\u3067\u3057\u305F" \u09AC\u09B2\u09AC\u09C7\u09A8 \u09A8\u09BE; \u09B8\u09B0\u09BE\u09B8\u09B0\u09BF "\u3044\u3044\u3048\u3001\u307E\u3060\u3067\u3059" (\u09A8\u09BE, \u098F\u0996\u09A8\u0993 \u0995\u09B0\u09BF\u09A8\u09BF) \u09AC\u09B2\u09AC\u09C7\u09A8\u0964'
      ],
      nihomiSenseiTipsBn: '\u09AC\u09B8 \u09AC\u09BE \u09B6\u09BF\u0995\u09CD\u09B7\u0995 \u099C\u09BF\u099C\u09CD\u099E\u09C7\u09B8 \u0995\u09B0\u09B2\u09C7: "\u3082\u3046 \u3057\u3085\u304F\u3060\u3044\u3092 \u3057\u307E\u3057\u305F\u304B" (\u0987\u09A4\u09BF\u09AE\u09A7\u09CD\u09AF\u09C7 \u09B9\u09CB\u09AE\u0993\u09DF\u09BE\u09B0\u09CD\u0995 \u0995\u09B0\u09C7\u099B?), \u09B9\u09B2\u09C7 "\u306F\u3044\u3001\u3082\u3046 \u3057\u307E\u3057\u305F", \u09A8\u09BE \u09B9\u09B2\u09C7 "\u3044\u3044\u3048\u3001\u307E\u3060\u3067\u3059" \u09AC\u09B2\u09C1\u09A8\u0964',
      examples: [
        {
          japanese: "\u3084\u307E\u3060\u3055\u3093\u306B \u306F\u306A\u3092 \u3042\u3052\u307E\u3057\u305F\u3002",
          english: "I gave flowers to Mr. Yamada.",
          bengali: "\u0986\u09AE\u09BF \u0987\u09DF\u09BE\u09AE\u09BE\u09A6\u09BE \u09B8\u09BE\u09B9\u09C7\u09AC\u0995\u09C7 \u09AB\u09C1\u09B2 \u09A6\u09BF\u09DF\u09C7\u099B\u09BF\u0964"
        },
        {
          japanese: "\u3082\u3046 \u306B\u3082\u3064\u3092 \u304A\u304F\u308A\u307E\u3057\u305F\u304B\u3002\u3044\u3044\u3048\u3001\u307E\u3060\u3067\u3059\u3002",
          english: "Have you already sent the parcel? No, not yet.",
          bengali: "\u09AA\u09BE\u09B0\u09CD\u09B8\u09C7\u09B2 \u0995\u09BF \u0987\u09A4\u09BF\u09AE\u09A7\u09CD\u09AF\u09C7 \u09AA\u09BE\u09A0\u09BF\u09DF\u09C7 \u09A6\u09BF\u09DF\u09C7\u099B\u09C7\u09A8? \u09A8\u09BE, \u098F\u0996\u09A8\u0993 \u09AA\u09BE\u09A0\u09BE\u0987\u09A8\u09BF\u0964"
        }
      ]
    }
