      options: ["\u304B\u3089", "\u3051\u3069", "\u306E\u3067", "\u307E\u3067"],
      correctIndex: 0,
      explanationBn: "\u0995\u09BE\u09B0\u09A3 \u09A8\u09BF\u09B0\u09CD\u09A6\u09C7\u09B6 \u0995\u09B0\u09A4\u09C7 \u09AC\u09BE\u0995\u09CD\u09AF\u09C7\u09B0 \u09B6\u09C7\u09B7\u09C7 \u304B\u3089 \u09AC\u09B8\u09C7 (\u3042\u308A\u307E\u305B\u3093\u304B\u3089)\u0964",
