      questionJa: "\u306B\u3082\u3064\u3092\uFF08\u3000\uFF09\u307E\u3057\u3087\u3046\u304B\u3002\u3048\u3048\u3001\u304A\u306D\u304C\u3044\u3057\u307E\u3059\u3002",
      questionBn: "\u09AE\u09BE\u09B2\u09BE\u09AE\u09BE\u09B2 \u09AC\u09B9\u09A8 \u0995\u09B0\u09C7 \u09A6\u09C7\u0993\u09DF\u09BE\u09B0 \u09B8\u09BE\u09B9\u09BE\u09AF\u09CD\u09AF\u09C7\u09B0 \u09AA\u09CD\u09B0\u09B8\u09CD\u09A4\u09BE\u09AC\u09C7 \u0995\u09CB\u09A8\u099F\u09BF \u09AC\u09B8\u09AC\u09C7?",
      type: "SINGLE_CHOICE",
      options: ["\u3082\u3061", "\u3082\u3063\u3066", "\u3082\u3064", "\u3082\u3063\u305F"],
      correctIndex: 0,
      explanationBn: "\u09B8\u09BE\u09B9\u09BE\u09AF\u09CD\u09AF\u09C7\u09B0 \u09AA\u09CD\u09B0\u09B8\u09CD\u09A4\u09BE\u09AC\u09C7 \u0995\u09CD\u09B0\u09BF\u09DF\u09BE-\u09B8\u09CD\u099F\u09C7\u09AE\u09C7\u09B0 \u09AA\u09B0 \u307E\u3057\u3087\u3046\u304B \u09AC\u09B8\u09C7 (\u3082\u3061\u307E\u3057\u3087\u3046\u304B)\u0964",
