      questionJa: "\u306D\u308B\uFF08\u3000\uFF09\u3001\u304A\u3075\u308D\u306B \u306F\u3044\u308A\u307E\u3059\u3002",
      questionBn: '\u0998\u09C1\u09AE\u09BE\u09A8\u09CB\u09B0 \u09AA\u09C2\u09B0\u09CD\u09AC\u09C7 \u09AC\u09BE\u09A5\u099F\u09BE\u09AC\u09C7 \u0997\u09CB\u09B8\u09B2 \u0995\u09B0\u09BF \u2014 "\u09AA\u09C2\u09B0\u09CD\u09AC\u09C7/\u0986\u0997\u09C7" \u09AC\u09CB\u099D\u09BE\u09A4\u09C7 \u0995\u09CB\u09A8\u099F\u09BF \u09AC\u09B8\u09C7?',
