        bengali: "\u09AE\u09BE, \u0986\u099C \u09A6\u09DF\u09BE \u0995\u09B0\u09C7 \u0986\u09AE\u09BE\u0995\u09C7 \u0986\u09B8\u09BE\u0995\u09C1\u09B8\u09BE \u0998\u09C1\u09B0\u09BF\u09DF\u09C7 \u09A6\u09C7\u0996\u09BE\u09A8\u09CB\u09B0 \u099C\u09A8\u09CD\u09AF \u0985\u09A8\u09C7\u0995 \u09A7\u09A8\u09CD\u09AF\u09AC\u09BE\u09A6\u0964",
        audioCue: "male_tokyo_polite"
