contentEngineRouter.get("/media/:storageKey(*)", async (req, res) => {
  try {
    const storageKey = req.params.storageKey;
    const buffer = await cloudStorageService.getFileBuffer(storageKey, cloudStorageService.mediaBucket);
    if (!buffer) {
      return res.status(404).json({ error: "Media file not found" });
    }
    const ext = path7.extname(storageKey).toLowerCase();
    const mimeTypes = {
      ".png": "image/png",
      ".jpg": "image/jpeg",
      ".jpeg": "image/jpeg",
      ".webp": "image/webp",
      ".svg": "image/svg+xml",
      ".gif": "image/gif",
      ".mp3": "audio/mpeg",
      ".wav": "audio/wav",
      ".ogg": "audio/ogg",
      ".m4a": "audio/m4a",
      ".pdf": "application/pdf"
    };
    const contentType = mimeTypes[ext] || "application/octet-stream";
    res.setHeader("Content-Type", contentType);
    res.setHeader("Content-Length", buffer.length);
    res.setHeader("Cache-Control", "public, max-age=86400, immutable");
    return res.send(buffer);
  } catch (err) {
    console.error("[ContentEngine] Get media error:", err);
    return res.status(500).json({ error: "Failed to retrieve media file" });
  }
});
