        phraseIndex,
        text: chunk,
        readingKana: chunk,
        romaji: chunk,
        morae,
        pattern,
        downstepMora,
        targetPitches,
        boundaryPitchMovement: bpm,
        hasPauseAfter: hasPause,
        pauseDurationMs,
